import { ethers } from "ethers";

const revertData = "";

// Parse the data word by word (32 bytes each)
const dataWithoutSelector = revertData.slice(10);
const words = [];
for (let i = 0; i < dataWithoutSelector.length; i += 64) {
  words.push(dataWithoutSelector.slice(i, i + 64));
}

console.log("Decoded words:");
words.forEach((w, i) => {
  console.log(`  Word ${i}: 0x${w}`);
  const num = BigInt("0x" + w);
  console.log(`    -> Decimal: ${num.toString()}`);
  
  // Try ASCII decoding
  try {
    const bytes = ethers.getBytes("0x" + w);
    const ascii = Array.from(bytes).map(b => b >= 32 && b <= 126 ? String.fromCharCode(b) : ".").join("");
    console.log(`    -> ASCII: ${ascii}`);
  } catch (e) {}
});
